<div class="card"><div class="card-body table-responsive"><table class="table table-bordered table-striped datatable"><thead><tr><th>No</th><th>Tanggal</th><th>Nama</th><th>WhatsApp</th><th>Email</th><th>Profesi</th><th>Ide Aplikasi</th><th>Keseriusan</th><th>Aksi</th></tr></thead><tbody><?php foreach ($pendaftar as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><?= date('d/m/Y H:i', strtotime($p->created_at)) ?></td><td><?= html_escape($p->nama) ?></td><td><?= html_escape($p->wa) ?></td><td><?= html_escape($p->email) ?></td><td><?= html_escape($p->profesi) ?></td><td><?= nl2br(html_escape($p->ide)) ?></td><td><?= html_escape($p->intent) ?></td><td><?= form_open('admin/pendaftar/hapus/'.$p->id, array('onsubmit'=>"return confirm('Hapus pendaftar ini?')")) ?><button class="btn btn-sm btn-danger"><i class="fas fa-trash"></i></button><?= form_close() ?></td></tr><?php endforeach; ?></tbody></table></div></div>
